<script setup lang="ts">
import {cloudApplications,applicationsState,createApplication,syncApplications} from '../services/remoteApplications'
import {cloudCommunity,cloudComment,cloudFollow,deleteCloudPost} from '../services/remoteCommunity'
import {computed,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {showToast,showConfirmDialog} from 'vant'
import {store,currentPets,toggleLike} from '../stores/community'
const route=useRoute(),router=useRouter(),post=computed(()=>store.posts.find(p=>p.id===route.params.id)),comment=ref('')
const photos=computed(()=>post.value?.photos?.length?post.value.photos:post.value?.image?[post.value.image]:[])
const application=computed(()=>store.applications.find(a=>!a.received&&a.postId===post.value?.id&&a.status==='pending'))
const replying=ref(false),followingBusy=ref(false)
async function reply(){if(replying.value)return;if(!store.profile){router.push('/auth');return}if(!comment.value.trim()){showToast('请先输入评论');return}if(post.value?.remote){replying.value=true;try{await cloudComment(post.value,comment.value.trim());comment.value=''}catch(e){showToast((e as Error).message)}finally{replying.value=false}return}post.value?.comments.push({id:crypto.randomUUID(),author:store.profile.name,text:comment.value.trim()});comment.value=''}
async function follow(){if(followingBusy.value)return;if(post.value?.remote){followingBusy.value=true;try{await cloudFollow(post.value)}catch(e){showToast((e as Error).message)}finally{followingBusy.value=false}return}if(!store.profile){router.push('/auth');return}const author=post.value!.author;store.following=store.following.includes(author)?store.following.filter(a=>a!==author):[...store.following,author]}
async function remove(){try{await showConfirmDialog({title:'删除帖子',message:post.value?.remote?'确定删除这条云端帖子吗？删除后其他用户也将无法查看。':'确定删除这条本机帖子吗？'});if(post.value!.remote)await deleteCloudPost(post.value!);else store.posts=store.posts.filter(p=>p.id!==post.value!.id);router.replace('/community')}catch(e){if(e instanceof Error)showToast(e.message)}}
async function apply(){const p=post.value;if(!p||p.mine||application.value)return;if(!currentPets.value.length){try{await showConfirmDialog({title:'先添加毛孩子吧',message:'请先创建你的宠物档案，再提交服务意向。',confirmButtonText:'去添加宠物',cancelButtonText:'暂时不添加'});await router.push({path:'/pets',query:{add:'1',next:route.fullPath}})}catch{}return}try{await showConfirmDialog({title:p.serviceRole==='offer'?'记录咨询意向':'记录接单意向',message:cloudApplications?'提交后，帖子作者可以看到你的昵称和意向。此操作不创建预约或订单。':'此操作仅保存在本机，不会联系对方，也不会创建真实预约或订单。'});if(cloudApplications){if(await createApplication(p))showToast('意向已提交，对方可在收到的意向中查看');return}store.applications.unshift({id:crypto.randomUUID(),postId:p.id,title:p.title,direction:p.serviceRole==='offer'?'buyer':'provider',status:'pending',createdAt:Date.now()});showToast('意向已记录到本机，未发送给对方')}catch(e){if(e instanceof Error)showToast(e.message)}}
</script>
<template><main><RouterLink to="/community" class="back"><van-icon name="arrow-left"/> 返回社区</RouterLink><article v-if="post" class="card detail-card"><div class="detail-author"><img :src="post.avatar" class="avatar" alt=""/><div><b>{{post.author}}</b><small>{{new Date(post.createdAt).toLocaleDateString('zh-CN')}}{{post.sample?' · 示例内容':''}}</small></div><button v-if="!post.mine" class="soft-button" @click="follow">{{store.following.includes(post.ownerId||post.author)?'已关注':'＋ 关注'}}</button><template v-else><RouterLink :to="{path:'/publish',query:{edit:post.id}}" class="soft-button">编辑</RouterLink><button class="text-button" @click="remove">删除</button></template></div><van-swipe v-if="photos.length" class="detail-gallery" :loop="false" indicator-color="#8b6cc9"><van-swipe-item v-for="(src,index) in photos" :key="index"><img class="detail-image" :src="src" :alt="post.title+' 图片 '+(index+1)"/></van-swipe-item></van-swipe><span class="pill">{{post.category}}{{post.kind==='service'?(post.serviceRole==='offer'?' · 提供服务':' · 找服务'):''}}</span><h1>{{post.title}}</h1><div v-if="post.location||post.when||post.petIds?.length" class="post-info"><p v-if="post.location"><van-icon name="location-o"/> {{post.location}}</p><p v-if="post.when"><van-icon name="clock-o"/> {{post.when}}</p><p v-if="post.petIds?.length">关联宠物：{{post.petIds.map(id=>currentPets.find(p=>p.id===id)?.name||'档案已删除').join('、')}}</p></div><p class="detail-copy">{{post.content}}</p><section v-if="post.kind==='service'" class="service-detail"><p v-if="applicationsState.error" role="alert">{{applicationsState.error}} <button @click="syncApplications().catch(()=>{})">刷新重试</button></p><div><span>{{post.serviceKind||'宠物服务'}}</span><strong>{{post.price?'¥'+post.price:'费用待商议'}}</strong></div><van-button v-if="!post.mine" block round :loading="applicationsState.busy[post.id]" :disabled="!!application||applicationsState.loading||!!applicationsState.error" color="#8b6cc9" @click="apply">{{application?(cloudApplications?'已提交意向':'已记录意向（未发送）'):post.serviceRole==='offer'?'咨询服务':'我来接单'}}</van-button><p>未接入真实沟通、人员核验、预约、支付及订单。</p><RouterLink to="/community">返回社区查看我的服务意向 ›</RouterLink></section><button class="soft-button" @click="toggleLike(post)"><van-icon :name="post.liked?'like':'like-o'"/> {{post.likes}} 人喜欢</button><h3>评论 · {{post.comments.length}}</h3><div v-for="c in post.comments" :key="c.id" class="comment"><b>{{c.author}}</b><p>{{c.text}}</p></div><p v-if="!post.comments.length" class="muted">友善的第一条评论，从你开始。</p><van-field v-model="comment" maxlength="300" placeholder="说点温暖的话…"><template #button><van-button size="small" :loading="replying" color="#a078b9" @click="reply">发送</van-button></template></van-field></article><van-empty v-else description="帖子不存在或已删除"><RouterLink to="/community" class="primary-link">返回社区</RouterLink></van-empty><p class="end-note">{{cloudCommunity?'点赞、评论和关注保存在云端；服务意向也已同步云端，不构成预约或订单。':'互动与意向仅保存在当前浏览器。'}}</p></main></template>
<style scoped>.detail-gallery{border-radius:17px;margin-bottom:18px;overflow:hidden}.detail-gallery .detail-image{display:block;margin:0;height:280px;object-fit:cover}.post-info{display:flex;flex-direction:column;gap:6px;margin:12px 0;font-size:12px;line-height:1.6;color:#85808c}.post-info p{display:flex;align-items:baseline;gap:5px;margin:0;overflow-wrap:anywhere}.post-info .van-icon{flex:none;color:#98939e}.service-detail{padding:15px;background:#f4edf9;border-radius:17px;margin:20px 0}.service-detail>div{display:flex;justify-content:space-between;margin-bottom:15px;font-size:13px;color:#6b6086}.service-detail strong{font-size:18px;color:#c2410c}.service-detail p{font-size:10px;color:#9a86a6;margin:10px 0}.service-detail>a{font-size:11px;color:#2563eb}</style>
